patches.find:
return rows.map(function (l) {
  var st = slaState(l);
  return '<button class="ld-lrow" onclick="ldOpen(' + l.id + ')">' +
    '<span class="ld-dot" style="background:' + (st === 'late' ? '#DC2626' : st === 'soon' ? '#D97706' : 'var(--bdr)') + '"></span>' +
    '<span class="ld-lname">' + esc(l.full_name || '(no name)') + '</span>' +
    '<span class="ld-lsub">' + esc([l.property_address, l.property_size].filter(Boolean).join(' · ') || l.email || '') + '</span>' +
    '<span class="ld-stage">' + esc(LABEL[l.stage] || l.stage) + '</span>' +
    '<span class="ld-own">' + esc(l.owner ? teamName(l.owner) : '—') + '</span>' +
    '<span class="ld-lago">' + ago(l.created_time || l.updated_at) + '</span>' +
    '</button>';
}).join('');

patches.replace:
return rows.map(function (l) {
  var st = slaState(l);
  var arch = !!l.archived_at;
  // A div rather than a button, because the Restore control is itself a
  // button and a button inside a button is not valid HTML - Chrome drops it.
  return '<div class="ld-lrow" role="button" tabindex="0" onclick="ldOpen(' + l.id + ')"' +
    ' onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();ldOpen(' + l.id + ')}">' +
    '<span class="ld-dot" style="background:' + (st === 'late' ? '#DC2626' : st === 'soon' ? '#D97706' : 'var(--bdr)') + '"></span>' +
    '<span class="ld-lname">' + esc(l.full_name || '(no name)') + '</span>' +
    '<span class="ld-lsub">' +
      esc([l.property_address, l.property_size].filter(Boolean).join(' · ') || l.email || '') +
      (arch && l.archive_reason ? '<span class="ld-why"> — ' + esc(l.archive_reason) + '</span>' : '') +
    '</span>' +
    '<span class="ld-stage">' + esc(LABEL[l.stage] || l.stage) + '</span>' +
    '<span class="ld-own">' + esc(l.owner ? teamName(l.owner) : '—') + '</span>' +
    '<span class="ld-lago">' + ago(l.created_time || l.updated_at) + '</span>' +
    (arch ? '<button class="btn sm ld-restore" title="Put this lead back on the board"' +
      ' onclick="event.stopPropagation();ldArchive(' + l.id + ',1)">↩ Restore</button>' : '') +
    '</div>';
}).join('');

window.ldView = function (v) {
  view = v; openId = null; sheet = null;
  // The archive is read as rows - a board of everything-stuck-at-one-stage is
  // not a board, and the Restore control lives on the row.
  if (v === 'archive') listMode = true; else if (v === 'board') listMode = false;
  reload();
};

if (restore) {
  var l2 = lead(id);
  toast('Restored' + (l2 && l2.owner ? ' to ' + teamName(l2.owner) : '') + ' — back on the board.');
  reload(); return;
}
